import{_ as r,o as a,c as t,an as o}from"./chunks/framework.CliSN-dr.js";const g=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"background.md","filePath":"background.md","lastUpdated":null}'),n={name:"background.md"};function s(i,e,l,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="History" tabindex="-1">History <a class="header-anchor" href="#History" aria-label="Permalink to &quot;History {#History}&quot;">​</a></h1><p><strong>Beginnings.</strong> Biophysical modelling applies the physics of heat, mass and momentum transfer to organisms (<a href="https://doi.org/10.2307/1948545" target="_blank" rel="noreferrer">Porter &amp; Gates 1969</a>; Gates 1980). Warren Porter took it up to answer a question about the <a href="https://en.wikipedia.org/wiki/Desert_iguana" target="_blank" rel="noreferrer">desert iguana</a>: what is the thermal advantage of changing colour from dark to light? With mechanical engineers he built a heat budget for the lizard (<a href="https://doi.org/10.1007/BF00379617" target="_blank" rel="noreferrer">Porter et al. 1973</a>), a microclimate model of the desert to drive it (Mitchell et al. 1975), and a clear-sky solar radiation model (<a href="https://doi.org/10.2307/1933806" target="_blank" rel="noreferrer">McCullough &amp; Porter 1971</a>). The same models gave water loss, energy requirements and predator-prey constraints (<a href="https://doi.org/10.2307/1443867" target="_blank" rel="noreferrer">Porter &amp; James 1979</a>), and Tracy (<a href="https://doi.org/10.2307/1942256" target="_blank" rel="noreferrer">1976</a>) extended them to wet-skinned ectotherms such as frogs.</p><p><strong>Endotherms.</strong> For birds and mammals the heat budget is solved for the metabolic or water loss rate that balances it, rather than for body temperature (<a href="https://doi.org/10.1071/ZO9940125" target="_blank" rel="noreferrer">Porter et al. 1994</a>; <a href="https://doi.org/10.1093/icb/40.4.597" target="_blank" rel="noreferrer">2000</a>).</p><p><strong>Landscapes.</strong> From 1998 the calculations were applied across landscapes (<a href="https://doi.org/10.1093/icb/42.3.431" target="_blank" rel="noreferrer">Porter et al. 2002</a>) and developed into mechanistic species distribution models that map the fundamental niche to space (<a href="https://doi.org/10.1890/03-0820" target="_blank" rel="noreferrer">Kearney &amp; Porter 2004</a>; <a href="https://doi.org/10.1111/j.1461-0248.2008.01277.x" target="_blank" rel="noreferrer">2009</a>). The suite of microclimate, ectotherm and endotherm models became known as Niche Mapper.</p><p><strong>Dynamic Energy Budgets.</strong> Metabolic, digestive, growth and reproduction rates were at first allometric functions of mass and temperature. Dynamic Energy Budget theory replaced these with an integrated, thermodynamically grounded account of the whole life cycle (<a href="https://doi.org/10.1098/rstb.2010.0034" target="_blank" rel="noreferrer">Kearney et al. 2010</a>; <a href="https://doi.org/10.1111/j.1365-2435.2011.01917.x" target="_blank" rel="noreferrer">Kearney 2012</a>; <a href="https://doi.org/10.1111/1365-2435.12020" target="_blank" rel="noreferrer">Kearney et al. 2013</a>).</p><p><strong>NicheMapR.</strong> The Fortran models were given an R interface as <a href="https://github.com/mrke/NicheMapR" target="_blank" rel="noreferrer">NicheMapR</a>: the microclimate model (<a href="https://doi.org/10.1111/ecog.02360" target="_blank" rel="noreferrer">Kearney &amp; Porter 2017</a>) with soil moisture (<a href="https://doi.org/10.1016/j.jhydrol.2018.04.040" target="_blank" rel="noreferrer">Kearney &amp; Maino 2018</a>) and snow (<a href="https://doi.org/10.1111/geb.13100" target="_blank" rel="noreferrer">Kearney 2020</a>), the ectotherm and DEB models (<a href="https://doi.org/10.1111/ecog.04680" target="_blank" rel="noreferrer">Kearney &amp; Porter 2019</a>), the endotherm model (<a href="https://doi.org/10.1111/ecog.05550" target="_blank" rel="noreferrer">Kearney et al. 2021</a>) and egg and wet-skin water uptake (<a href="https://doi.org/10.1111/2041-210X.14018" target="_blank" rel="noreferrer">Kearney &amp; Enriquez-Urzelai 2022</a>).</p><p><strong>NicheMapper.jl.</strong> The Julia ecosystem separates these models into packages with clear interfaces, so each part can be tested, swapped and differentiated on its own; see the <a href="./architecture/mechanistic_niche_modelling_framework">Architecture overview</a>.</p><p>Tests and applications of the NicheMapR models are listed on the <a href="https://mrke.github.io/" target="_blank" rel="noreferrer">NicheMapR website</a>: <a href="https://mrke.github.io/tests/" target="_blank" rel="noreferrer">tests</a> and <a href="https://mrke.github.io/examples/" target="_blank" rel="noreferrer">applications</a>.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p>Gates, D. M. (1980). <em>Biophysical Ecology</em>. Springer.</p></li><li><p>Mitchell, J. W., Beckman, W. A., Bailey, R. T., &amp; Porter, W. P. (1975). Microclimatic modeling of the desert. In <em>Heat and Mass Transfer in the Biosphere</em> (pp. 275–286). Scripta.</p></li></ul>',10)])])}const m=r(n,[["render",s]]);export{g as __pageData,m as default};
